/**
 * API token rows. The secret is stored only as a hash, and no function here
 * ever returns it: every read maps to the hash-free `ApiToken`.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { getDb, apiTokens } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp } from "./_mappers";
import type { ApiTokenRow } from "@/server/db";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { ApiToken } from "@/types/api-token";

function toApiToken(row: ApiTokenRow): ApiToken {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    name: row.name,
    scope: row.scope,
    prefix: row.prefix,
    expiresAt: brandStamp(row.expiresAt),
    lastUsedAt: row.lastUsedAt === null ? null : brandStamp(row.lastUsedAt),
    revokedAt: row.revokedAt === null ? null : brandStamp(row.revokedAt),
    createdAt: brandStamp(row.createdAt),
  };
}

export type NewApiToken = ApiToken & { tokenHash: string };

/**
 * Inserts the token unless the user already holds `limit` usable tokens in the
 * org. Count and insert run in one synchronous transaction, so concurrent
 * creates cannot both slip under the limit. Returns `null` when over limit.
 */
export async function insertApiTokenWithinLimit(
  token: NewApiToken,
  now: IsoTimestamp,
  limit: number,
): Promise<ApiToken | null> {
  const db = getDb();
  return db.transaction((tx) => {
    const used = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, token.orgId),
          eq(apiTokens.userId, token.userId),
          isNull(apiTokens.revokedAt),
          gt(apiTokens.expiresAt, now),
        ),
      )
      .get();
    if ((used?.value ?? 0) >= limit) return null;

    const row = tx.insert(apiTokens).values(token).returning().get();
    return toApiToken(row);
  });
}

export async function listApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), sql`rowid desc`)
    .all();
  return rows.map(toApiToken);
}

export async function findApiToken(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Revokes a not-yet-revoked token; `null` when it was already revoked. */
export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

